import { createFileRoute } from '@tanstack/react-router';
import { ProjectForm } from '../features/projects/ProjectForm';
import { ProjectsList } from '../features/projects/ProjectsList';

// The projects page: one new file under routes/. It composes its own feature's form + list; each
// queries for itself, so this page holds no data and no state.
export const Route = createFileRoute('/projects/')({
  component: ProjectsPage,
});

function ProjectsPage() {
  return (
    <section data-testid="projects-page">
      <h1>Projects</h1>
      <ProjectForm />
      <ProjectsList />
    </section>
  );
}

import { createFileRoute } from '@tanstack/react-router';
import { ProjectDetail } from '../slots/defs/projectDetail';

// A project's detail page: a new file under routes/, reached by project-open-<id>. It holds no data
// and no state — it renders the project.detail region with the project id from the URL, and each
// panel (invoices table, total, add form) is its own *.slot.tsx that queries for itself.
export const Route = createFileRoute('/projects/$projectId')({
  component: ProjectDetailPage,
});

function ProjectDetailPage() {
  const { projectId } = Route.useParams();
  return (
    <section data-testid="project-page">
      <h1>Project</h1>
      <ProjectDetail.Slot projectId={Number(projectId)} />
    </section>
  );
}

import { useQuery } from '@tanstack/react-query';
import { projectsKey, listProjects, type Project } from './api';
import { ProjectRow } from '../../slots/defs/projectRow';
import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
import { useSearchParam, asFlag, asNumber, asString } from '../../url/useSearchParam';

// The projects list. Reads server data under ['projects'] (never copied into state); the create form
// shares the key, so a successful create refreshes this list with no import between them. Each row
// shows the client's NAME, which the server joins onto the project.
//
// Archived projects are tucked away: they drop off the list unless the `showArchived` URL key is on.
// The toggle control (its own *.slot.tsx) owns that key; this list reads the same key and filters,
// so they stay in step through the shared search param with nothing passed between them.
export function ProjectsList() {
  const [showArchived] = useSearchParam('showArchived', asFlag);
  // The tag filter control (its own *.slot.tsx) owns this key; the list reads the same key and keeps
  // only the projects carrying that tag, so they stay in step through the shared search param with
  // nothing passed between them. Unset clears the key, so the list falls back to every project.
  const [tagFilter] = useSearchParam('projectTag', asNumber);
  // The status filter control (its own *.slot.tsx) owns this key; the list reads the same key and
  // keeps only the projects at that lifecycle status, so they stay in step through the shared
  // search param with nothing passed between them. An empty key means every status.
  const [statusFilter] = useSearchParam('projectStatus', asString);
  const { data: projects } = useQuery({ queryKey: projectsKey, queryFn: listProjects });

  if (!projects) {
    return null;
  }

  const visible = projects.filter(
    (project: Project) =>
      (showArchived || !project.archived) &&
      (tagFilter === undefined || project.tagIds.includes(tagFilter)) &&
      (statusFilter === '' || project.status === statusFilter),
  );

  return (
    <>
      <ProjectsToolbar.Slot />
      {visible.length === 0 ? (
        <p data-testid="projects-empty">No projects yet.</p>
      ) : (
        <ProjectsTable projects={visible} />
      )}
    </>
  );
}

function ProjectsTable({ projects }: { projects: Project[] }) {
  return (
    <table data-testid="projects-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Client</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {projects.map((project: Project) => (
          <tr key={project.id} data-testid={`project-row-${project.id}`}>
            <td data-testid="project-name">{project.name}</td>
            <td data-testid="project-client">{project.clientName}</td>
            <td>
              <ProjectRow.Slot projectId={project.id} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import {
  clientsKey,
  createProject,
  listClientOptions,
  projectsKey,
  projectStatuses,
  type ProjectStatus,
} from './api';

// Add a project for a client. The fields the user is typing live in useState (uncommitted input);
// the saved data lives on the server. The client select is populated from the ['clients'] query —
// each option's value is the client id — so the user picks which client the project is for. On
// success we invalidate ['projects'] so the list refetches — we never hand-maintain the list.
export function ProjectForm() {
  const queryClient = useQueryClient();
  const { data: clients } = useQuery({ queryKey: clientsKey, queryFn: listClientOptions });
  const [name, setName] = useState('');
  const [clientId, setClientId] = useState('');
  // The lifecycle the new project starts in — uncommitted input like name/client, so it lives in
  // useState until submit. Defaults to ACTIVE, the state a fresh project gets.
  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');

  const mutation = useMutation({
    mutationFn: createProject,
    onSuccess: () => {
      setName('');
      setClientId('');
      setStatus('ACTIVE');
      void queryClient.invalidateQueries({ queryKey: projectsKey });
    },
  });

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim() === '' || clientId === '') {
      return;
    }
    mutation.mutate({ name: name.trim(), clientId: Number(clientId), status });
  };

  return (
    <form onSubmit={submit}>
      <input
        data-testid="project-form-name"
        placeholder="Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
      <select
        data-testid="project-form-client"
        value={clientId}
        onChange={(e) => setClientId(e.target.value)}
      >
        <option value="">Select a client</option>
        {(clients ?? []).map((client) => (
          <option key={client.id} value={client.id}>
            {client.name}
          </option>
        ))}
      </select>
      <select
        data-testid="project-form-status"
        value={status}
        onChange={(e) => setStatus(e.target.value as ProjectStatus)}
      >
        {projectStatuses.map((s) => (
          <option key={s} value={s}>
            {s}
          </option>
        ))}
      </select>
      <button data-testid="project-form-submit" type="submit">
        Add project
      </button>
    </form>
  );
}

import { useQuery } from '@tanstack/react-query';
import { allInvoicesKey, listAllInvoices, type AllInvoice } from './allInvoices';
import { formatMoney } from '../../ui/money';
import { AllInvoicesToolbar } from '../../slots/defs/allInvoicesToolbar';
import { useSearchParam, asString, asNumber } from '../../url/useSearchParam';

// One place listing every invoice across all projects. Reads server data under ['invoices', 'all']
// (never copied into state); each row shows which PROJECT the invoice is for (the name the server
// joins on) and what STAGE it is at (its status). Amounts render with two decimals.
//
// The chosen stage lives in the URL under the shared `invoiceStatus` key — the filter control (its
// own *.slot.tsx) writes it, this list reads it. It is part of the query key, so each stage caches
// on its own and the server returns the rows already narrowed.
export function AllInvoices() {
  const [status] = useSearchParam('invoiceStatus', asString);
  // Which page to show lives in the URL under the shared `invoicePage` key — the pagination control
  // (its own *.slot.tsx) writes it, this list reads it. It is part of the query key, so each page
  // caches on its own and the server returns just that window of rows.
  const [page] = useSearchParam('invoicePage', asNumber);
  const pageNumber = page ?? 1;
  const { data: invoices } = useQuery({
    queryKey: [...allInvoicesKey, status, pageNumber],
    queryFn: () => listAllInvoices(status, pageNumber),
  });

  return (
    <>
      <AllInvoicesToolbar.Slot />
      <AllInvoicesList invoices={invoices} />
    </>
  );
}

function AllInvoicesList({ invoices }: { invoices: AllInvoice[] | undefined }) {
  if (!invoices) {
    return null;
  }

  if (invoices.length === 0) {
    return <p data-testid="all-invoices-empty">No invoices yet.</p>;
  }

  return (
    <table data-testid="all-invoices-table">
      <thead>
        <tr>
          <th>Project</th>
          <th>Status</th>
          <th>Amount</th>
        </tr>
      </thead>
      <tbody>
        {invoices.map((invoice: AllInvoice) => (
          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
            <td data-testid="invoice-project">{invoice.projectName}</td>
            <td data-testid="invoice-status">{invoice.status}</td>
            <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

import { useQuery } from '@tanstack/react-query';
import { useSearchParam, asString } from '../../url/useSearchParam';
import {
  clientsKey,
  projectsKey,
  listClients,
  listProjects,
  type SearchClient,
  type SearchProject,
} from './api';

// One search box that looks across BOTH clients and projects. The committed term lives in the URL
// under 'q' (not useState — it outlives the click and is shareable/back-button friendly), so the box
// owns the key and the results read the same key. Each kind queries for itself under its shared key
// (['clients'], ['projects']) — nothing is imported from those features. Matching is a
// case-insensitive substring on the name; an empty box shows nothing until the user types.
export function GlobalSearch() {
  const [query, setQuery] = useSearchParam('q', asString);
  const { data: clients } = useQuery({ queryKey: clientsKey, queryFn: listClients });
  const { data: projects } = useQuery({ queryKey: projectsKey, queryFn: listProjects });

  const needle = query.trim().toLowerCase();
  const clientMatches = needle
    ? (clients ?? []).filter((c: SearchClient) => c.name.toLowerCase().includes(needle))
    : [];
  const projectMatches = needle
    ? (projects ?? []).filter((p: SearchProject) => p.name.toLowerCase().includes(needle))
    : [];

  return (
    <section data-testid="global-search-panel">
      <input
        data-testid="global-search"
        type="search"
        placeholder="Search clients and projects"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <div data-testid="search-clients">
        <h2>Clients</h2>
        {clientMatches.map((c: SearchClient) => (
          <div key={c.id} data-testid={`client-row-${c.id}`}>
            <span data-testid="client-name">{c.name}</span>
          </div>
        ))}
      </div>
      <div data-testid="search-projects">
        <h2>Projects</h2>
        {projectMatches.map((p: SearchProject) => (
          <div key={p.id} data-testid={`project-row-${p.id}`}>
            <span data-testid="project-name">{p.name}</span>
          </div>
        ))}
      </div>
    </section>
  );
}

