import { useQuery } from '@tanstack/react-query';
import { ClientDetail } from '../../slots/defs/clientDetail';
import { clientSummaryKey, getClientSummary } from './api';

// At-a-glance counts for one client — a small badge panel filling the top of the client.detail
// region (order 10, above the projects and contacts tables). Reads server data under
// ['clients', clientId, 'summary'] (never copied into state); the server does the counting, so this
// just renders the two figures the client-projects-count / client-contacts-count anchors expose.
function ClientCounts({ clientId }: { clientId: number }) {
  const { data } = useQuery({
    queryKey: clientSummaryKey(clientId),
    queryFn: () => getClientSummary(clientId),
  });

  if (!data) {
    return null;
  }

  return (
    <dl data-testid="client-counts">
      <dt>Projects</dt>
      <dd data-testid="client-projects-count">{data.projects}</dd>
      <dt>Contacts</dt>
      <dd data-testid="client-contacts-count">{data.contacts}</dd>
    </dl>
  );
}

export const contribution = ClientDetail.fill({ order: 10, Component: ClientCounts });

import { useQuery } from '@tanstack/react-query';
import { dashboardKey, getDashboard } from './api';
import { formatMoney } from '../../ui/money';

// The home dashboard: three figures summarising the whole workspace. Reads server data under
// ['dashboard'] (never copied into state); the figures are computed server-side so the page holds
// no arithmetic — it just renders. The outstanding total is money, shown with two decimal places.
export function Dashboard() {
  const { data } = useQuery({ queryKey: dashboardKey, queryFn: getDashboard });

  if (!data) {
    return null;
  }

  return (
    <dl data-testid="dashboard">
      <dt>Clients</dt>
      <dd data-testid="dashboard-clients-count">{data.clients}</dd>
      <dt>Projects</dt>
      <dd data-testid="dashboard-projects-count">{data.projects}</dd>
      <dt>Outstanding</dt>
      <dd data-testid="dashboard-outstanding-total">{formatMoney(data.outstanding)}</dd>
      <dt>Overdue</dt>
      <dd data-testid="dashboard-overdue-count">{data.overdue}</dd>
    </dl>
  );
}

import { ClientDetail } from '../../slots/defs/clientDetail';
import { useSearchParam, asFlag } from '../../url/useSearchParam';

// A control over the client's projects panel — one new *.slot.tsx filling the client.detail region
// (ordered just above the projects table). It owns the `clientProjectsAll` URL key; the projects
// panel reads the same key and reveals the finished and hidden (archived) projects when it is on.
// Nothing is passed between them: they stay in step through the shared search param. Off clears the
// key, so the panel falls back to showing only the active projects.
function ClientProjectsShowAll() {
  const [showAll, setShowAll] = useSearchParam('clientProjectsAll', asFlag);
  return (
    <button
      data-testid="client-projects-show-all"
      type="button"
      aria-pressed={showAll}
      onClick={() => setShowAll(showAll ? undefined : true)}
    >
      {showAll ? 'Show active only' : 'Show all projects'}
    </button>
  );
}

export const contribution = ClientDetail.fill({ order: 15, Component: ClientProjectsShowAll });

